// MemoryWithEmbedding pairs a memory entry with its embedding for batch operations
type MemoryWithEmbedding struct {
	Entry     MemoryEntry
	Embedding []float32
}

// StoreMemoryBatch stores multiple memory entries with their embeddings
func (s *QdrantStorage) StoreMemoryBatch(ctx context.Context, entries []MemoryWithEmbedding) error {
	if len(entries) == 0 {
		return nil
	}

	s.mu.Lock()
	defer s.mu.Unlock()

	if s.closed {
		return ErrStorageClosed
	}

	points := make([]*qdrant.PointStruct, len(entries))
	for i, mwe := range entries {
		points[i] = s.memoryToPoint(mwe.Entry, mwe.Embedding)
	}

	_, err := s.client.Upsert(ctx, &qdrant.UpsertPoints{
		CollectionName: s.collectionName,
		Points:         points,
	})
	if err != nil {
		return fmt.Errorf("failed to batch store memories: %w", err)
	}

	return nil
}

// MemoryListOptions configures how memory entries are listed
type MemoryListOptions struct {
	Limit  int          // Maximum number of entries to return (0 = no limit)
	Offset int          // Number of entries to skip
	Tags   []string     // Filter by tags (any match)
	Source string       // Filter by source
	Status MemoryStatus // Filter by status
}

// MemoryStats holds memory usage statistics
type MemoryStats struct {
	ChunksInMemory   int
	EmbeddingBytes   int64
	EstimatedTotalMB float64
}

// memoryResultHelp is the --axi next-step list for memory-search.
func memoryResultHelp(total int) []string {
	if total == 0 {
		return []string{
			"Lower the cutoff with `--threshold 0` and drop filters",
			"Run `llm-semantic memory list` to see what is stored",
		}
	}
	return []string{"Run `llm-semantic memory list` to browse stored entries"}
}

// TestQdrantStorage_MemoryTagFiltering pins the post-search tag filter, which
// Qdrant cannot express server-side, including its case-insensitivity.
func TestQdrantStorage_MemoryTagFiltering(t *testing.T) {
	storage, _ := newFakeQdrantStorage(t, "memtags", 4)
	ctx := context.Background()

	entries := []MemoryWithEmbedding{
		{Entry: MemoryEntry{ID: "m1", Question: "q1", Answer: "a1", Tags: []string{"Go", "storage"}, Status: MemoryStatusPending}, Embedding: []float32{1, 0, 0, 0}},
		{Entry: MemoryEntry{ID: "m2", Question: "q2", Answer: "a2", Tags: []string{"python"}, Status: MemoryStatusPending}, Embedding: []float32{1, 0, 0, 0}},
		{Entry: MemoryEntry{ID: "m3", Question: "q3", Answer: "a3", Tags: nil, Status: MemoryStatusPending}, Embedding: []float32{1, 0, 0, 0}},
	}
	if err := storage.StoreMemoryBatch(ctx, entries); err != nil {
		t.Fatalf("StoreMemoryBatch: %v", err)
	}

	listed, err := storage.ListMemory(ctx, MemoryListOptions{Tags: []string{"GO"}})
	if err != nil {
		t.Fatalf("ListMemory: %v", err)
	}
	if len(listed) != 1 || listed[0].ID != "m1" {
		t.Fatalf("ListMemory by tag returned %v, want only m1", listed)
	}

	searched, err := storage.SearchMemory(ctx, []float32{1, 0, 0, 0}, MemorySearchOptions{TopK: 10, Tags: []string{"python"}})
	if err != nil {
		t.Fatalf("SearchMemory: %v", err)
	}
	if len(searched) != 1 || searched[0].Entry.ID != "m2" {
		t.Fatalf("SearchMemory by tag returned %v, want only m2", searched)
	}
}

// backfillMemoryFTS5 populates the memory FTS5 index from existing memory entries.
func (s *SQLiteStorage) backfillMemoryFTS5() error {
	var ftsCount, memoryCount int

	err := s.db.QueryRow(`SELECT COUNT(*) FROM memory_fts`).Scan(&ftsCount)
	if err != nil {
		return fmt.Errorf("failed to count memory FTS entries: %w", err)
	}

	err = s.db.QueryRow(`SELECT COUNT(*) FROM memory`).Scan(&memoryCount)
	if err != nil {
		return fmt.Errorf("failed to count memory entries: %w", err)
	}

	if memoryCount > 0 && ftsCount == 0 {
		_, err := s.db.Exec(`
			INSERT INTO memory_fts(rowid, question, answer)
			SELECT rowid, COALESCE(question, ''), COALESCE(answer, '')
			FROM memory
		`)
		if err != nil {
			return fmt.Errorf("failed to backfill memory FTS5: %w", err)
		}
	}

	return nil
}

// MemoryStatsTracker is an optional interface for tracking memory retrieval statistics.
// Storage implementations that support memory stats should implement this interface.
type MemoryStatsTracker interface {
	// TrackMemoryRetrieval records a single memory retrieval event.
	TrackMemoryRetrieval(ctx context.Context, memoryID string, query string, score float32) error

	// TrackMemoryRetrievalBatch records multiple memory retrieval events in a single transaction.
	TrackMemoryRetrievalBatch(ctx context.Context, retrievals []MemoryRetrieval, query string) error

	// GetMemoryStats returns stats for a specific memory entry.
	GetMemoryStats(ctx context.Context, memoryID string) (*RetrievalStats, error)

	// GetAllMemoryStats returns stats for all tracked memories.
	GetAllMemoryStats(ctx context.Context) ([]RetrievalStats, error)

	// GetMemoryRetrievalHistory returns recent retrieval log entries for a memory.
	GetMemoryRetrievalHistory(ctx context.Context, memoryID string, limit int) ([]RetrievalLogEntry, error)

	// PruneMemoryRetrievalLog removes retrieval log entries older than the specified duration.
	PruneMemoryRetrievalLog(ctx context.Context, olderThanDays int) (int64, error)

	// UpdateMemoryStatsStatus updates the status of a memory entry.
	UpdateMemoryStatsStatus(ctx context.Context, memoryID string, status string) error
}

func entryIDs(entries []MemoryEntry) []string {
	out := make([]string, len(entries))
	for i, e := range entries {
		out[i] = e.ID
	}
	return out
}

// BenchmarkSearchMemory_LargeIndex benchmarks SearchMemory with a large index
// to verify constant memory usage across batch processing
func BenchmarkSearchMemory_LargeIndex(b *testing.B) {
	// Use temp file for better benchmark accuracy
	tmpDir := b.TempDir()
	dbPath := filepath.Join(tmpDir, "bench.db")
	storage, err := NewSQLiteStorage(dbPath, 384)
	if err != nil {
		b.Fatalf("Failed to create storage: %v", err)
	}
	defer storage.Close()

	// Create a large number of memory entries (10,000)
	const numEntries = 10000
	embeddingDim := 384

	// Pre-generate embeddings to avoid allocation in store loop (not realistic but necessary for benchmark purity)
	// In real benchmarks, embeddings come from an API, but here we generate them
	// This is just creating the dataset, not what we're benchmarking
	queryEmbedding := makeEmbedding(embeddingDim, 0.0)

	// Store entries in batches
	const batchSize = 100
	var entries []MemoryWithEmbedding
	for i := 0; i < numEntries; i++ {
		embedding := makeEmbedding(embeddingDim, float32(i)*0.01)
		entry := MemoryWithEmbedding{
			Entry: MemoryEntry{
				Question:    "Test Question " + itoa(i),
				Answer:      "Test Answer " + itoa(i),
				Tags:        []string{"bench", "test", itoa(i % 10)},
				Source:      "benchmark",
				Status:      "active",
				Occurrences: i + 1,
			},
			Embedding: embedding,
		}
		entries = append(entries, entry)
		if len(entries) >= batchSize {
			if err := storage.StoreMemoryBatch(context.Background(), entries); err != nil {
				b.Fatalf("Failed to store batch: %v", err)
			}
			entries = entries[:0]
		}
	}
	if len(entries) > 0 {
		if err := storage.StoreMemoryBatch(context.Background(), entries); err != nil {
			b.Fatalf("Failed to store final batch: %v", err)
		}
	}

	// Reset timer to measure only search performance
	b.ResetTimer()

	// Benchmark the search
	for i := 0; i < b.N; i++ {
		_, err := storage.SearchMemory(context.Background(), queryEmbedding, MemorySearchOptions{
			TopK:      10,
			Threshold: 0.0,
		})
		if err != nil {
			b.Fatalf("SearchMemory failed: %v", err)
		}
	}
}
